def json_bytes(report):
    return (json.dumps(report, ensure_ascii=True, sort_keys=True, indent=2) + '\n').encode('utf-8')


def esc(value):
    return escape(str(value), quote=True)


def hours(seconds):
    return f'{seconds / 3600:.2f} h'


